for (const [language, additions] of Object.entries({"zh":{"FAQ":"常见问题","VISUAL":"影像","INTL":"国际","LASER HAIR REMOVAL · SKIN CARE · BEAUTY":"激光脱毛 · 皮肤护理 · 美容","03 · MIKI SKIN SPA ACADEMY":"03 · Miki Skin Spa Academy","MIKI SKIN SPA · EDUCATION":"Miki Skin Spa · 培训","Hotline / Zalo":"电话 / Zalo","Hotline: 0935 555 170":"电话：0935 555 170","QR Facebook Miki Beauty Spa":"Miki Skin Spa 的 Facebook 二维码","QR Telegram Miki Skin Spa":"Miki Skin Spa 的 Telegram 二维码","QR Zalo Miki Skin Spa":"Miki Skin Spa 的 Zalo 二维码","Website":"网站"},"ru":{"FAQ":"Вопросы","VISUAL":"ФОТО","INTL":"ГОСТИ","LASER HAIR REMOVAL · SKIN CARE · BEAUTY":"ЛАЗЕРНОЕ УДАЛЕНИЕ ВОЛОС · УХОД ЗА КОЖЕЙ · КРАСОТА","03 · MIKI SKIN SPA ACADEMY":"03 · Miki Skin Spa Academy","MIKI SKIN SPA · EDUCATION":"Miki Skin Spa · ОБУЧЕНИЕ","Hotline / Zalo":"Телефон / Zalo","Hotline: 0935 555 170":"Телефон: 0935 555 170","QR Facebook Miki Beauty Spa":"QR-код Facebook Miki Skin Spa","QR Telegram Miki Skin Spa":"QR-код Telegram Miki Skin Spa","QR Zalo Miki Skin Spa":"QR-код Zalo Miki Skin Spa","Website":"Сайт"},"en":{"FAQ":"FAQ","VISUAL":"VISUAL","INTL":"INTL","LASER HAIR REMOVAL · SKIN CARE · BEAUTY":"LASER HAIR REMOVAL · SKIN CARE · BEAUTY","03 · MIKI SKIN SPA ACADEMY":"03 · Miki Skin Spa Academy","MIKI SKIN SPA · EDUCATION":"Miki Skin Spa · EDUCATION","Hotline / Zalo":"Phone / Zalo","Hotline: 0935 555 170":"Phone: 0935 555 170","QR Facebook Miki Beauty Spa":"Miki Skin Spa Facebook QR code","QR Telegram Miki Skin Spa":"Miki Skin Spa Telegram QR code","QR Zalo Miki Skin Spa":"Miki Skin Spa Zalo QR code","Website":"Website"}})) Object.assign(window.MIKI_STATIC_TRANSLATIONS[language], additions);
